import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Assets Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Assets Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/assets-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Assets Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/assets-overview"}]]},"headers":[],"relativePath":"user-guide/assets-overview.md","filePath":"user-guide/assets-overview.md","lastUpdated":1787354383000}'),i={name:"user-guide/assets-overview.md"};function d(r,e,n,l,c,u){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="assets-module" tabindex="-1">Assets Module <a class="header-anchor" href="#assets-module" aria-label="Permalink to &quot;Assets Module&quot;">​</a></h1><p>Operations module on the frozen platform. A workspace register of company equipment and fixed assets — number, name, status, category, identity fields, purchase/warranty details, assignment, notes, and an activity timeline — with <strong>soft, optional</strong> links to Vendors and Employees. Assets is <strong>standalone</strong>: it installs with no hard module dependencies and works fully on its own.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/assets">assets.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/assets">assets.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/assets">assets.md</a></td></tr><tr><td>Module Development Standard</td><td><a href="/developer-guide/module-development">module-development.md</a></td></tr><tr><td>Reference blueprint</td><td><a href="/user-guide/vendors-overview">vendors-overview.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-assets">../api/tenant-v1-assets.md</a></td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><ul><li>Auto-number (<code>AST-</code> prefix, configurable via <code>assets_number_prefix</code>)</li><li>Name, status (<code>active</code> / <code>in_repair</code> / <code>retired</code> / <code>disposed</code>), category enum</li><li>Manufacturer, model, serial number, free-text location</li><li>Purchase date, purchase cost, currency, warranty end date</li><li>Assignment (<code>created_by</code> / <code>assigned_to</code>) with assignee scoping via <code>assets.assign</code></li><li>Optional <code>vendor_id</code> and <code>employee_id</code> — soft links, only validated (and only pickable in the UI) when the corresponding module is entitled</li><li>Notes + activity timeline</li><li>Table view with search, status/category/assignee filters, and <strong>My Assets</strong> toggle</li><li>KPIs via <code>GET /assets/stats</code> (total, my assets, unassigned, active, in repair, retired, disposed)</li><li>Trash filtering plus <strong>Restore</strong> and <strong>Delete permanently</strong></li><li>Module licensing (<code>module:assets</code>) + Spatie permissions — <strong>free Marketplace opt-in</strong>, no hard dependencies</li><li>Audit + activity logging</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p><code>assets.view</code> · <code>create</code> · <code>update</code> · <code>delete</code> · <code>restore</code> · <code>force.delete</code> · <code>assign</code></p><p>Enable Assets from Marketplace (free). Catalog: slug <code>assets</code>, category <code>operations</code> (Operations), <code>is_default_included = false</code>, <code>is_billable = false</code>, <code>sort_order = 80</code>, version <strong>1.0.0</strong>.</p><h2 id="soft-links-not-install-dependencies" tabindex="-1">Soft links (not install dependencies) <a class="header-anchor" href="#soft-links-not-install-dependencies" aria-label="Permalink to &quot;Soft links (not install dependencies)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Link</th><th>When usable</th></tr></thead><tbody><tr><td>Vendor</td><td>Vendors module entitled</td></tr><tr><td>Employee (custodian)</td><td>Employees module entitled</td></tr><tr><td>Workspace assignee</td><td>Always (platform user)</td></tr></tbody></table><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Depreciation / Accounting journals</li><li>Product / Inventory / Warehouse FKs</li><li>Maintenance tickets → Help Desk</li><li>Attachments / barcodes / QR</li><li>Dashboard widget</li><li>Automation triggers</li></ul>',13)])])}const h=t(i,[["render",d]]);export{m as __pageData,h as default};
